### 🎨 原型产物一：`GroupChatSlotHost`（React 19 UI Slots 纯净卸载守卫）

适配 `dsh-super-injector` 插件热重载机制，利用 React 19 `useEffect` 与 `AbortController` 建立注销阻断网，确保面板拔插时 **DOM 零残留、悬挂异步瞬时斩断**：

```tsx
import React, { useEffect, useRef, useState } from 'react';

export interface GroupChatSlotHostProps {
  slotId: string;
  traceId: string;
  onSlotUnmount?: (slotId: string) => void;
  children: (abortSignal: AbortSignal) => React.ReactNode;
}

export const GroupChatSlotHost: React.FC<GroupChatSlotHostProps> = ({
  slotId,
  traceId,
  onSlotUnmount,
  children,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [abortController] = useState(() => new AbortController());

  useEffect(() => {
    // 注入全局 trace 标识，防止多 Agent 串流污染
    if (containerRef.current) {
      containerRef.current.dataset.slotId = slotId;
      containerRef.current.dataset.traceId = traceId;
    }

    return () => {
      // 1. 瞬时阻断正在流转的渲染请求与悬挂动画
      abortController.abort();
      // 2. 清理外部可能挂载的全局监听与插槽通信
      if (onSlotUnmount) onSlotUnmount(slotId);
      // 3. 彻底释放宿主 DOM 引用，防止热重载幽灵内存泄漏
      if (containerRef.current) {
        containerRef.current.innerHTML = '';
      }
    };
  }, [slotId, traceId, abortController, onSlotUnmount]);

  return (
    <div
      ref={containerRef}
      className="dsh-slot-host-wrapper transition-opacity duration-200 ease-out"
    >
      {children(abortController.signal)}
    </div>
  );
};

