### 🎨 原型切片二：`DecisionCard`（Task F2 · 决策卡片与防双击重入交互）

杜绝普通文本罗列选项，专为 `group_chat_ask_user` 协议打造结构化交互卡片。自带 Loading 锁态、微动效与键盘快捷键无障碍支持：

```tsx
import React, { useState } from 'react';

export interface DecisionOption {
  key: string;
  label: string;
  description?: string;
  recommended?: boolean;
}

export interface DecisionCardProps {
  cardId: string;
  title: string;
  prompt: string;
  options: DecisionOption[];
  onSelect: (selectedKey: string) => Promise<void>;
  disabled?: boolean;
}

export const DecisionCard: React.FC<DecisionCardProps> = ({
  cardId,
  title,
  prompt,
  options,
  onSelect,
  disabled = false,
}) => {
  const [submittingKey, setSubmittingKey] = useState<string | null>(null);

  const handleChoose = async (key: string) => {
    if (disabled || submittingKey) return; // 严格防重入与防并发双击
    setSubmittingKey(key);
    try {
      await onSelect(key);
    } finally {
      setSubmittingKey(null);
    }
  };

  return (
    <div
      data-card-id={cardId}
      className="dsh-decision-card my-3 p-4 rounded-xl border border-amber-500/30 bg-amber-950/10 backdrop-blur-md shadow-lg transition-all"
    >
      <div className="flex items-center gap-2 mb-2">
        <span className="inline-block w-2.5 h-2.5 rounded-full bg-amber-400 animate-pulse" />
        <h4 className="text-sm font-semibold text-amber-200 tracking-wide">{title}</h4>
      </div>
      <p className="text-xs text-neutral-300 mb-3 leading-relaxed">{prompt}</p>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
        {options.map((opt) => {
          const isSelected = submittingKey === opt.key;
          const isPendingOther = submittingKey !== null && !isSelected;

          return (
            <button
              key={opt.key}
              type="button"
              disabled={disabled || submittingKey !== null}
              onClick={() => handleChoose(opt.key)}
              className={`relative text-left p-3 rounded-lg border text-xs transition-all duration-150 flex flex-col justify-between
                ${
                  opt.recommended
                    ? 'border-amber-400/60 bg-amber-500/10 hover:bg-amber-500/20 text-amber-100 ring-1 ring-amber-400/40'
                    : 'border-neutral-700 bg-neutral-800/60 hover:bg-neutral-700/60 text-neutral-200'
                }
                ${isPendingOther ? 'opacity-40 cursor-not-allowed' : ''}
                ${isSelected ? 'scale-[0.98] border-amber-400 ring-2 ring-amber-400' : ''}
              `}
            >
              <div className="font-medium flex items-center justify-between">
                <span>{opt.label}</span>
                {opt.recommended && (
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-300 font-mono">
                    推荐
                  </span>
                )}
              </div>
              {opt.description && (
                <span className="text-[11px] text-neutral-400 mt-1 line-clamp-2">
                  {opt.description}
                </span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
