import React, { useState, useTransition } from 'react';

export interface DecisionOption {
  id: string;
  label: string;
  description?: string;
  variant?: 'primary' | 'secondary' | 'danger';
}

export interface DecisionCardProps {
  decisionId: string;
  title: string;
  description?: string;
  options: DecisionOption[];
  onSelect: (decisionId: string, optionId: string) => Promise<void> | void;
  disabled?: boolean;
}

export const DecisionCard: React.FC<DecisionCardProps> = ({
  decisionId,
  title,
  description,
  options,
  onSelect,
  disabled = false,
}) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const handleSelect = (optionId: string) => {
    // 拦截重入：一旦锁定或处于提交中，拒绝后续任何点击
    if (disabled || selectedId !== null || isPending) {
      return;
    }

    // 1. 同步上锁
    setSelectedId(optionId);

    // 2. React 19 异步转换，挂载 Pending 态，防重复派发
    startTransition(async () => {
      try {
        await onSelect(decisionId, optionId);
      } catch (err) {
        // 允许在上层抛出错误时解除本地锁定（或保持状态依业务决定）
        console.error('[DecisionCard] submit failed:', err);
        setSelectedId(null);
      }
    });
  };

