      if (onSlotUnmount) onSlotUnmount(slotId);
      // 3. 彻底释放宿主 DOM 引用，防止热重载幽灵内存泄漏
      if (containerRef.current) {
        containerRef.current.innerHTML = '';
      }
    };
  }, [slotId, traceId, abortController, onSlotUnmount]);

  return (
    <div
      ref={containerRef}
      className="dsh-slot-host-wrapper transition-opacity duration-200 ease-out"
    >
      {children(abortController.signal)}
    </div>
  );
};

