import React, { useEffect, useRef, useState, useTransition } from 'react';

export interface GroupChatSlotHostProps {
  slotId: string;
  traceId: string;
  onUnmountCleanup?: () => void;
}

export const GroupChatSlotHost: React.FC<GroupChatSlotHostProps> = ({ slotId, traceId, onUnmountCleanup }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    // 1. 初始化当前插槽上下文的 AbortController
    const controller = new AbortController();
    abortControllerRef.current = controller;

    return () => {
      // 2. 触发中断信号，终止所有挂载在此插槽上的未竟异步与流式读取
      controller.abort();

      // 3. 彻底解绑宿主 DOM 引用与净身出户清理
      if (containerRef.current) {
        containerRef.current.innerHTML = '';
      }

      // 4. 回调通知宿主注入器注销 Slot 资源
      onUnmountCleanup?.();
    };
  }, [slotId, traceId, onUnmountCleanup]);

  return <div ref={containerRef} id={`group-chat-slot-${slotId}`} className="dsh-slot-host-root" />;
};

