### 🎨 交付切片一：`useRafStreamBuffer`（React 19 流式防抖与顺滑渲染）
针对长流式 Token 频繁触发 React 重新渲染导致的微卡顿与掉帧，采用 `requestAnimationFrame` 双缓冲聚合，杜绝 UI 抽搐：

```tsx
import { useEffect, useRef, useState, useTransition } from 'react';

export interface UseRafStreamBufferOptions {
  batchIntervalMs?: number;
  onFlush?: (text: string) => void;
}

export function useRafStreamBuffer(options: UseRafStreamBufferOptions = {}) {
  const [displayText, setDisplayText] = useState('');
  const [isPending, startTransition] = useTransition();
  const bufferRef = useRef('');
  const rafHandleRef = useRef<number | null>(null);

  const appendChunk = (chunk: string) => {
    bufferRef.current += chunk;

    if (rafHandleRef.current === null) {
      rafHandleRef.current = requestAnimationFrame(() => {
        // 使用 React 19 Concurrent 调度，保证输入响应高优
        startTransition(() => {
          setDisplayText(bufferRef.current);
          options.onFlush?.(bufferRef.current);
        });
        rafHandleRef.current = null;
      });
    }
  };

  const reset = () => {
    if (rafHandleRef.current !== null) {
      cancelAnimationFrame(rafHandleRef.current);
      rafHandleRef.current = null;
    }
    bufferRef.current = '';
    setDisplayText('');
  };

  useEffect(() => {
    return () => {
      if (rafHandleRef.current !== null) {
        cancelAnimationFrame(rafHandleRef.current);
      }
    };
  }, []);

  return { displayText, appendChunk, reset, isPending };
}

