### 🎨 交付切片二：`DecisionCard`（人机决策交互卡片与防双击幂等锁）

针对人类用户连续狂点、网络抖动重入、多角色同时触发决策卡片造成的并发污染，卡片设计了「本地即刻上锁 + React 19 Action Pending + 唯一 actionId 校验」三道防线：

```tsx
import React, { useState, useTransition } from 'react';

export interface DecisionOption {
  id: string;
  label: string;
  description?: string;
  variant?: 'primary' | 'secondary' | 'danger';
}

export interface DecisionCardProps {
  decisionId: string;
  title: string;
  description?: string;
  options: DecisionOption[];
  onSelect: (decisionId: string, optionId: string) => Promise<void> | void;
  disabled?: boolean;
}

export const DecisionCard: React.FC<DecisionCardProps> = ({
  decisionId,
  title,
  description,
  options,
  onSelect,
  disabled = false,
}) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const handleSelect = (optionId: string) => {
    // 拦截重入：一旦锁定或处于提交中，拒绝后续任何点击
    if (disabled || selectedId !== null || isPending) {
      return;
    }

    // 1. 同步上锁
    setSelectedId(optionId);

    // 2. React 19 异步转换，挂载 Pending 态，防重复派发
    startTransition(async () => {
      try {
        await onSelect(decisionId, optionId);
      } catch (err) {
        // 允许在上层抛出错误时解除本地锁定（或保持状态依业务决定）
        console.error('[DecisionCard] submit failed:', err);
        setSelectedId(null);
      }
    });
  };

  return (
    <div
      className="dsh-decision-card border rounded-lg p-4 my-2 shadow-sm bg-background"
      data-decision-id={decisionId}
      role="region"
      aria-label={title}
    >
      <div className="font-semibold text-base mb-1">{title}</div>
      {description && <div className="text-sm text-muted-foreground mb-3">{description}</div>}

      <div className="flex flex-wrap gap-2">
        {options.map((opt) => {
          const isSelected = selectedId === opt.id;
          const isBusy = isPending && isSelected;

          return (
            <button
              key={opt.id}
              type="button"
              disabled={disabled || (selectedId !== null && !isSelected) || isPending}
              onClick={() => handleSelect(opt.id)}
              className={`px-3 py-1.5 rounded text-sm transition-all flex items-center gap-1.5 ${
                isSelected
                  ? 'bg-primary text-primary-foreground font-medium shadow'
                  : 'bg-secondary hover:bg-secondary/80 text-secondary-foreground'
              } disabled:opacity-50 disabled:cursor-not-allowed`}
              aria-pressed={isSelected}
            >
              {isBusy && <span className="animate-spin text-xs">⏳</span>}
              <span>{opt.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};
